-- Fashion 083: wz_itemequipdata 可选镜像（已于 2026-07-20 手工导入 xiaoye1）
-- 回滚 ID 列表: .eval_append/fashion_083_equipdata_itemids_20260719_231008.txt
-- 策略: CREATE IF NOT EXISTS + INSERT ... WHERE NOT EXISTS（可重复执行）
-- =============================================================================
-- Fashion 083 装备数值镜像（可选）
-- 说明：BeiDou 运行时从 Character.wz XML 读装备属性（ItemInformationProvider.equipData），
--       本库表不参与热路径。本脚本按 079/HeavenMS 的 wz_itemequipdata 结构生成，便于对照/导入。
-- 策略：仅 INSERT 本次 Character 同步涉及的 itemid；已存在行用 NOT EXISTS 跳过。
-- 回滚：DELETE FROM wz_itemequipdata WHERE itemid IN (...见同目录 id 列表...);
-- =============================================================================

CREATE TABLE IF NOT EXISTS `wz_itemequipdata` (
  `id` INT NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `itemid` INT NOT NULL COMMENT '装备物品ID（对应 Character 条目）',
  `itemLevel` INT NOT NULL DEFAULT -1 COMMENT '装备成长等级；-1 表示基础属性',
  `key` VARCHAR(30) NOT NULL COMMENT '属性键（reqLevel/cash/incPAD 等）',
  `value` INT NOT NULL DEFAULT 0 COMMENT '属性值',
  PRIMARY KEY (`id`),
  KEY `idx_itemid` (`itemid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='装备属性KV（可选镜像，非BeiDou热路径）';

INSERT INTO `wz_itemequipdata` (`itemid`,`itemLevel`,`key`,`value`)
SELECT 1032338, -1, 'cash', 1 FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM `wz_itemequipdata` e
  WHERE e.itemid=1032338 AND e.itemLevel=-1 AND e.`key`='cash'
);
